using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace SptAssistantSetup {
 internal sealed class InstallerForm:Form {
  readonly Label title=new Label(),intro=new Label(),steps=new Label(),pathLabel=new Label(),modeLabel=new Label(),languageLabel=new Label(),phase=new Label(),footer=new Label();
  readonly TextBox path=new TextBox(),message=new TextBox();readonly Button browse=new Button(),install=new Button(),close=new Button(),logs=new Button(),backup=new Button(),admin=new Button();
  readonly RadioButton full=new RadioButton(),client=new RadioButton();readonly ComboBox language=new ComboBox();readonly ProgressBar progress=new ProgressBar();
  bool english,busy,completed;InstallResult result;
  internal InstallerForm(string selected,bool clientOnly,string uiLanguage){
   english=uiLanguage=="en";Text="SPT Assistant Setup 2.3.1";ClientSize=new Size(770,610);MinimumSize=new Size(720,620);StartPosition=FormStartPosition.CenterScreen;AutoScaleMode=AutoScaleMode.Dpi;Font=new Font("Microsoft YaHei UI",10);BackColor=Color.FromArgb(247,249,252);
   var table=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(26,22,26,16),ColumnCount=1,RowCount=11};
   int[] heights={46,28,38,78,92,40,30,12,96,44,24};for(int row=0;row<heights.Length;row++)table.RowStyles.Add(new RowStyle(row==8?SizeType.Percent:SizeType.Absolute,row==8?100:heights[row]));Controls.Add(table);
   title.Font=new Font(Font.FontFamily,22,FontStyle.Bold);title.ForeColor=Color.FromArgb(21,43,66);intro.ForeColor=Color.DimGray;steps.ForeColor=Color.FromArgb(0,97,160);
   Add(table,title);Add(table,intro);Add(table,steps);
   var location=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2};location.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));location.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,112));location.RowStyles.Add(new RowStyle(SizeType.Absolute,30));location.RowStyles.Add(new RowStyle(SizeType.Absolute,40));pathLabel.Dock=DockStyle.Fill;location.Controls.Add(pathLabel,0,0);location.SetColumnSpan(pathLabel,2);path.Dock=DockStyle.Fill;path.Margin=new Padding(0,4,10,0);browse.Dock=DockStyle.Fill;browse.Margin=new Padding(0,0,0,2);location.Controls.Add(path,0,1);location.Controls.Add(browse,1,1);table.Controls.Add(location);
   var modes=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};modes.RowStyles.Add(new RowStyle(SizeType.Absolute,27));modes.RowStyles.Add(new RowStyle(SizeType.Absolute,32));modes.RowStyles.Add(new RowStyle(SizeType.Absolute,32));Add(modes,modeLabel);Add(modes,full);Add(modes,client);table.Controls.Add(modes);full.Checked=!clientOnly;client.Checked=clientOnly;
   var langPanel=new FlowLayoutPanel{Dock=DockStyle.Fill};languageLabel.AutoSize=true;languageLabel.Padding=new Padding(0,5,10,0);language.DropDownStyle=ComboBoxStyle.DropDownList;language.Items.AddRange(new object[]{"简体中文","English"});language.Width=150;language.SelectedIndex=english?1:0;langPanel.Controls.Add(languageLabel);langPanel.Controls.Add(language);table.Controls.Add(langPanel);
   Add(table,phase);progress.Dock=DockStyle.Fill;table.Controls.Add(progress);
   message.Multiline=true;message.ReadOnly=true;message.BorderStyle=BorderStyle.None;message.BackColor=BackColor;message.Dock=DockStyle.Fill;message.Margin=new Padding(0,12,0,0);message.ScrollBars=ScrollBars.Vertical;table.Controls.Add(message);
   var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,WrapContents=false};foreach(var button in new[]{install,close,admin,backup,logs}){button.Size=new Size(126,36);button.Margin=new Padding(8,0,0,0);buttons.Controls.Add(button);}table.Controls.Add(buttons);
   install.BackColor=Color.FromArgb(0,103,179);install.ForeColor=Color.White;install.FlatStyle=FlatStyle.Flat;install.FlatAppearance.BorderSize=0;logs.Visible=backup.Visible=admin.Visible=false;footer.ForeColor=Color.DimGray;footer.Font=new Font(Font.FontFamily,8);Add(table,footer);
   path.Text=selected;path.AllowDrop=true;path.DragEnter+=delegate(object sender,DragEventArgs e){if(e.Data.GetDataPresent(DataFormats.FileDrop))e.Effect=DragDropEffects.Copy;};path.DragDrop+=delegate(object sender,DragEventArgs e){try{path.Text=InstallerEngine.NormalizeGameRoot(((string[])e.Data.GetData(DataFormats.FileDrop))[0]);}catch{}};
   browse.Click+=Browse;install.Click+=delegate{if(completed)Close();else BeginInstall();};close.Click+=delegate{Close();};logs.Click+=delegate{if(result!=null&&File.Exists(result.Log))Process.Start("notepad.exe",InstallerEngine.QuoteArgument(result.Log));};backup.Click+=delegate{if(result!=null&&Directory.Exists(result.Backup))Process.Start("explorer.exe",InstallerEngine.QuoteArgument(result.Backup));};admin.Click+=Elevate;
   language.SelectedIndexChanged+=delegate{english=language.SelectedIndex==1;ApplyText();};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;MessageBox.Show(this,T("Installation is in progress. Please wait for completion.","正在安装并备份，请等待完成后再关闭窗口。"),Text,MessageBoxButtons.OK,MessageBoxIcon.Information);}};
   Shown+=async delegate{if(path.Text.Length==0){var candidates=await Task.Run(()=>InstallerEngine.DetectGames());if(!IsDisposed&&path.Text.Length==0&&candidates.Length==1)path.Text=candidates[0];else if(!IsDisposed&&candidates.Length>1)message.Text=T("Multiple game folders found. Select the copy you want to use.","找到了多个游戏目录，请选择你平时使用的那一份。");}};
   ApplyText();
  }
  static void Add(TableLayoutPanel table,Control control){control.Dock=DockStyle.Fill;control.Margin=Padding.Empty;table.Controls.Add(control);}
  string T(string en,string zh){return english?en:zh;}
  void ApplyText(){
   title.Text=T("SPT Assistant · Setup 2.3.1","SPT 辅助 · 安装 2.3.1");intro.Text=T("Offline installer · automatic backups · existing settings retained","离线安装 · 自动备份 · 保留已有设置");steps.Text=T("1  Choose your game     2  Install     3  Open the game, press Right Shift","① 选择游戏位置     ② 一键安装     ③ 进游戏按右 Shift");pathLabel.Text=T("Game folder — you can also drop a folder or game EXE here","游戏位置 — 也可以拖入游戏文件夹或 EXE");browse.Text=T("Browse…","选择游戏…");modeLabel.Text=T("How do you play?","你平时怎么玩？");full.Text=T("Single-player / hosting friends (recommended)","单人游戏 / 自己当联机房主（推荐）");client.Text=T("Joining a friend's server — client only","加入朋友的联机 — 仅安装客户端");languageLabel.Text=T("Language","界面语言");install.Text=completed?T("Done","完成"):T("Install now","开始安装");close.Text=T("Close","关闭");logs.Text=T("View log","查看日志");backup.Text=T("Open backup","打开备份");admin.Text=T("Retry as admin","管理员重试");footer.Text=T("For SPT 5.0 BE / EFT 48558. No manual file copying required.","适用 SPT 5.0 BE / EFT 48558，无需手动复制文件。");
   if(!busy&&!completed&&result==null){phase.Text=T("Ready","准备安装");message.Text=T("Choose EscapeFromTarkov.exe from your SPT installation. Close the game and SPT server, then click Install now.","请选择 SPT 目录中的 EscapeFromTarkov.exe。关闭游戏和 SPT 服务端后，点击“开始安装”。");}
  }
  void Browse(object sender,EventArgs args){using(var dialog=new OpenFileDialog{Title=T("Select the game or SPT launcher","选择你的游戏或 SPT 启动器"),Filter="Tarkov / SPT|EscapeFromTarkov.exe;SPT.Launcher.exe;SPT.Launcher*.exe;SPT.Server.exe|EXE|*.exe",CheckFileExists=true}){try{if(Directory.Exists(path.Text))dialog.InitialDirectory=path.Text;}catch{}if(dialog.ShowDialog(this)==DialogResult.OK)path.Text=InstallerEngine.NormalizeGameRoot(dialog.FileName);}}
  async void BeginInstall(){
   string selected;try{selected=InstallerEngine.NormalizeGameRoot(path.Text);}catch{message.Text=T("That location is not valid. Use Browse to select the game.","这个位置无效，请点击“选择游戏”重新选择。");return;}
   if(selected.Length==0){message.Text=T("Select your SPT game first.","请先选择你的 SPT 游戏。");return;}
   path.Text=selected;busy=true;result=null;logs.Visible=backup.Visible=admin.Visible=false;SetEditable(false);phase.Text=T("Checking…","正在检查…");message.Text=T("The installer will check the game, back up replaced files and install the mod.","安装程序会检查游戏、备份将替换的文件，然后安装模组。请稍候。");
   bool clientOnly=client.Checked;string chosen=english?"en":"ch";
   var reporter=new Progress<InstallProgress>(p=>{if(IsDisposed)return;progress.Value=p.Percent;phase.Text=Phase(p.Phase)+"  "+p.Percent+"%";});
   result=await Task.Run(()=>InstallerEngine.Run(selected,clientOnly,chosen,false,p=>((IProgress<InstallProgress>)reporter).Report(p)));
   busy=false;SetEditable(true);logs.Visible=File.Exists(result.Log);backup.Visible=Directory.Exists(result.Backup);
   if(result.Ok){completed=true;progress.Value=100;phase.Text=T("Installation complete","安装完成");message.Text=clientOnly?T("Connect to your friend's server with the SPT launcher. In game, press Right Shift to open Assistant.","通过 SPT 启动器连接朋友的服务器。进入游戏后按右 Shift 打开辅助菜单。"):T("Start SPT as usual: start the server, then use the SPT launcher. In game, press Right Shift to open Assistant.","照常启动 SPT：先开服务端，再用 SPT 启动器进入游戏。按右 Shift 打开辅助菜单。");install.Text=T("Done","完成");close.Visible=false;path.Enabled=browse.Enabled=full.Enabled=client.Enabled=language.Enabled=false;}
   else{phase.Text=T("Installation was not completed","暂未完成安装");message.Text=Friendly(result.Code);if(result.Backup.Length>0)message.Text+="\r\n"+(result.RollbackSucceeded?T("Changes were rolled back. Your backup is retained.","已尝试恢复原文件，备份仍保留。"):T("Some files could not be restored. Keep the backup and log for recovery.","部分文件未能恢复，请保留备份和日志用于恢复。"));admin.Visible=result.Code=="ACCESS_DENIED";}
  }
  void SetEditable(bool enabled){foreach(var control in new Control[]{path,browse,full,client,language,install,close})control.Enabled=enabled;}
  string Phase(string value){switch(value){case "EXTRACT":return T("Preparing installation","正在准备安装");case "CHECK_GAME":return T("Checking the game","正在检查游戏");case "CHECK_PACKAGE":return T("Checking package files","正在校验安装文件");case "CHECK_DATA":return T("Reading game data","正在读取游戏数据");case "BACKUP":return T("Backing up existing files","正在备份原有文件");case "RETIRE":return T("Migrating old modules","正在迁移旧模块");case "COPY":return T("Installing the mod","正在安装模组");case "SETUP":return T("Saving settings","正在保存设置");case "ROLLBACK":return T("Restoring original files","正在恢复原文件");case "COMPLETE":return T("Installation complete","安装完成");default:return T("Working…","正在处理…");}}
  internal string Friendly(string code){switch(code){case "GAME_NOT_FOUND":return T("The selected folder does not contain the game. Select EscapeFromTarkov.exe inside your SPT folder.","所选位置没有找到游戏。请点击“选择游戏”，选择 SPT 文件夹内的 EscapeFromTarkov.exe。");case "WRONG_GAME_VERSION":return T("This package requires SPT 5.0 BE / EFT 48558. Choose a matching SPT game, not the official online game.","游戏版本不匹配。此安装包适用 SPT 5.0 BE / EFT 48558，请选择对应的 SPT 游戏，不要选官方联机版。");case "DEPENDENCIES_MISSING":return T("SPT files are missing. Start the matching SPT game once, close it, then retry.","缺少 SPT 必要文件。请先通过对应的 SPT 启动器进入游戏一次，关闭后再安装。");case "SERVER_NOT_FOUND":return T("The SPT server was not found. Choose your complete SPT folder, or select client only if you join a friend.","没有找到 SPT 服务端。请选完整的 SPT 目录；如果是加入朋友的联机，请选择“仅安装客户端”。");case "DATABASE_MISSING":return T("The SPT installation is incomplete. Choose the complete SPT game folder.","这个 SPT 目录缺少游戏数据，请选择完整的 SPT 游戏目录。");case "GAME_RUNNING":return T("Close the game and SPT server, then click Install now again. The installer will not close them for you.","请先关闭游戏和 SPT 服务端，再点击“开始安装”。安装程序不会强行关闭它们。");case "PACKAGE_DAMAGED":return T("The installer is incomplete or damaged. Download the Setup.exe again from the official release page.","安装文件不完整或已损坏，请从正式发布页重新下载安装 EXE。");case "ACCESS_DENIED":return T("Windows denied write access. Use Retry as admin, or choose a game folder you can write to.","Windows 不允许写入所选目录。可点击“管理员重试”，或选择你有写入权限的游戏目录。");case "FILES_LOCKED":return T("A file is in use or could not be written. Close the game and server and retry. The log contains details.","文件正在被占用或无法写入。请关闭游戏和服务端后重试；详细原因可点“查看日志”。");case "ROLLBACK_FAILED":return T("Installation failed and recovery needs attention. Keep the backup and log; do not delete them.","安装失败，且部分恢复未完成。请保留备份和日志，不要删除它们。");default:return T("Installation could not finish. Close the game/server and retry, or send the installation log for help.","安装未能完成。请关闭游戏和服务端后重试，或提供安装日志以便排查。");}}
  void Elevate(object sender,EventArgs args){try{var start=new ProcessStartInfo(Application.ExecutablePath,"--game-root "+InstallerEngine.QuoteArgument(path.Text)+(client.Checked?" --client-only":"")+" --language "+(english?"en":"ch")){UseShellExecute=true,Verb="runas"};Process.Start(start);Close();}catch{message.Text=T("Administrator access was not granted. You can retry or choose another folder.","尚未获得管理员权限，可以重试或选择其他游戏目录。");}}
  static void RenderControls(Control parent,Graphics canvas,Point offset){foreach(Control child in parent.Controls){if(!child.Visible||child.Width<=0||child.Height<=0)continue;var point=new Point(offset.X+child.Left,offset.Y+child.Top);if(child.HasChildren)RenderControls(child,canvas,point);else using(var image=new Bitmap(child.Width,child.Height)){child.DrawToBitmap(image,new Rectangle(Point.Empty,child.Size));canvas.DrawImageUnscaled(image,point);}}}
  internal void Preview(string destination){english=false;language.SelectedIndex=0;path.Text=@"D:\Games\SPT";ApplyText();ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;Location=new Point(-32000,-32000);Show();Application.DoEvents();PerformLayout();Update();using(var bitmap=new Bitmap(ClientSize.Width,ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap)){graphics.Clear(BackColor);RenderControls(this,graphics,Point.Empty);}bitmap.Save(destination,System.Drawing.Imaging.ImageFormat.Png);}bool fits=title.Visible&&install.Visible&&install.PointToScreen(Point.Empty).Y+install.Height<=PointToScreen(new Point(ClientSize.Width,ClientSize.Height)).Y;Hide();if(!fits)throw new InvalidOperationException("Installer controls are not visible within the window.");}
 }
}
